"""Browser checks for replay behavior, recorded evidence, and responsive layout.
Usage: python scripts/verify-embodiedrsi.py --url http://localhost:4321
Requires Playwright and a Chromium installation; does not alter source records.
"""
import argparse,json,re
from pathlib import Path
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser();parser.add_argument('--url',required=True);parser.add_argument('--chromium',default=str(Path.home()/'.cache/ms-playwright/chromium-1243/chrome-linux64/chrome'));args=parser.parse_args()
root=Path(__file__).resolve().parents[1];out=root/'.work/embodiedrsi';out.mkdir(parents=True,exist_ok=True)
checks=[];errors=[];bad_assets=[]
def check(name,ok):
 checks.append({'check':name,'pass':bool(ok)})
 if not ok:raise AssertionError(name)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=args.chromium,headless=True,args=['--no-sandbox'])
 context=b.new_context(viewport={'width':1440,'height':1050},permissions=['clipboard-read','clipboard-write'])
 page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)))
 page.on('response',lambda r: bad_assets.append(f'{r.status} {r.url}') if r.status>=400 and '/embodied-rsi/' in r.url else None)
 page.goto(args.url,wait_until='networkidle');page.wait_for_selector('#replay:not([hidden])')
 page.wait_for_function('document.querySelector("#episode-video").readyState >= 2')
 check('Project title',page.title().startswith('EmbodiedEvo'))
 check('Primary evaluation is RoboDojo',page.locator('.results-title h3').inner_text()=='RoboDojo')
 check('Paper title matches',page.title()=='EmbodiedEvo: Self-improving Code Agents for Physical Intelligence')
 check('English document',page.locator('html').get_attribute('lang')=='en')
 check('No Chinese in page text',not re.search(r'[\u3400-\u9fff]',page.locator('body').inner_text()))
 check('Description results',page.locator('#input-panel-description tbody td').all_text_contents()==['14.77','8.50%','38.64','30.17%'])
 page.locator('#input-tab-wiki').click()
 check('Wiki results switch',page.locator('#input-panel-wiki').is_visible() and not page.locator('#input-panel-description').is_visible())
 check('Wiki result values',page.locator('#input-panel-wiki tbody td').all_text_contents()==['20.67','13.36%','42.42','35.08%'])
 page.locator('#input-tab-wiki').press('ArrowLeft')
 check('Result keyboard navigation',page.locator('#input-tab-description').get_attribute('aria-selected')=='true' and page.locator('#input-panel-description').is_visible())
 check('Full evaluation has all categories',page.locator('.category-row').count()==5)
 check('Four executor comparisons',page.locator('.transfer-card').count()==4)
 check('Representation costs',all(v in page.locator('.cost-cards').inner_text() for v in ['$4.058','$12.203','$5.732']))
 check('Raw-history uncertainty retained','−5.11 to 5.94' in page.locator('#experience').inner_text())
 page.locator('.hero-overview img, .paper-figure img').evaluate_all('(images)=>images.forEach(i=>i.loading="eager")')
 page.wait_for_function('Array.from(document.querySelectorAll(".hero-overview img, .paper-figure img")).every(i=>i.complete && i.naturalWidth>0)')
 check('Paper figures available',True)
 check('All section anchors resolve',page.locator('a[href^="#"]').evaluate_all('(links)=>links.every(a=>document.getElementById(a.hash.slice(1)))'))
 response=context.request.get(args.url.rstrip('/')+'/embodied-rsi/data/results.json')
 check('Downloadable results',response.ok and response.json()['fullEvaluation']['success']==37.82)
 for name in ['robotwin','robocasa']:
  d=json.loads((root/f'public/embodied-rsi/data/{name}.json').read_text())
  page.locator(f'[data-episode="{name}"]').click();page.wait_for_function('(n)=>document.querySelector("#episode-title").textContent===n',arg=d['title'])
  page.wait_for_function('document.querySelector("#episode-video").readyState >= 2')
  duration=page.locator('video').evaluate('(v)=>v.duration');check(name+' video duration',abs(duration-d['duration'])<.05)
  for index in [2,5,len(d['segments'])-1]:
   s=d['segments'][index];page.locator(f'[data-chapter="{index}"]').click()
   page.wait_for_function('(t)=>Math.abs(document.querySelector("#episode-video").currentTime-t)<0.1',arg=s['start']+.01)
   check(f'{name} execution {index} exact code',page.locator('#execution-code').inner_text()==s['code'])
   check(f'{name} execution {index} title',page.locator('#chapter-title').inner_text()==s['title'])
  check(name+' English trace',not re.search(r'[\u3400-\u9fff]',json.dumps(d,ensure_ascii=False)))
  check(name+' final success',page.locator('#execution-status').inner_text()=='Task success confirmed after this execution')
  check(name+' final next disabled',page.locator('#next-chapter').is_disabled())
  page.locator('#feedback-tab').click();check(name+' feedback includes real stdout',d['segments'][-1]['stdout'].strip() in page.locator('#execution-feedback').inner_text())
  page.locator('#code-tab').click();page.locator('#copy-code').click();check(name+' code copy',page.evaluate('navigator.clipboard.readText()')==d['segments'][-1]['code'])
  page.locator('#replay-start').click();check(name+' restart chapter',page.locator('#chapter-title').inner_text()=='Initial scene')
  page.locator('#playback-speed').select_option('2');check(name+' speed',page.locator('video').evaluate('(v)=>v.playbackRate')==2)
  page.locator('#play-toggle').click();page.wait_for_function('document.querySelector("#episode-video").currentTime>0.6')
  page.locator('#play-toggle').click();check(name+' play pause',page.locator('video').evaluate('(v)=>v.paused'))
  page.locator('#timeline-scrub').fill(str(d['segments'][5]['start']+.1));check(name+' scrubbing changes code',page.locator('#chapter-title').inner_text()==d['segments'][5]['title'])
  page.locator('#prev-chapter').click();check(name+' previous chapter',page.locator('#chapter-title').inner_text()==d['segments'][4]['title'])
 page.locator('[data-episode="robodojo"]').click();check('RoboDojo paper evidence state',page.locator('#dojo-empty').is_visible() and not page.locator('#replay').is_visible())
 check('RoboDojo deep link', 'episode=robodojo' in page.url)
 page.reload(wait_until='networkidle');check('RoboDojo deep link reload',page.locator('#dojo-empty').is_visible())
 page.locator('[data-show-twin]').click();page.wait_for_selector('#replay:not([hidden])')
 page.locator('#method-tab-0').click();page.locator('#method-tab-0').press('ArrowRight');check('Method keyboard navigation',page.locator('#method-tab-1').get_attribute('aria-selected')=='true' and page.locator('#method-title').inner_text()=='Turn feedback into knowledge.')
 page.locator('#method-tab-3').click();check('Test protocol', 'no reset or cross-scene learning' in page.locator('#method-description').inner_text())
 # Fast switching must not let a delayed response overwrite the user's selection.
 page.evaluate('''() => { document.querySelector('[data-episode="robocasa"]').click(); document.querySelector('[data-episode="robotwin"]').click(); document.querySelector('[data-episode="robodojo"]').click(); }''')
 page.wait_for_timeout(150);check('Rapid switch preserves latest selection',page.locator('#dojo-empty').is_visible() and not page.locator('#replay').is_visible())
 page.locator('[data-show-twin]').click();page.wait_for_selector('#replay:not([hidden])')
 page.locator('[data-chapter="5"]').click();page.evaluate('scrollTo(0,0)');page.wait_for_timeout(300)
 page.screenshot(path=str(out/'desktop.png'),full_page=True);page.locator('#replay').screenshot(path=str(out/'replay.png'));page.locator('.method-diagram').screenshot(path=str(out/'method.png'))
 for width in [320,390,768,1024,1440]:
  page.set_viewport_size({'width':width,'height':900});page.evaluate('scrollTo(0,0)');page.wait_for_timeout(100)
  check(f'No page overflow at {width}px',page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
  check(f'Hero title visible at {width}px',page.locator('h1').evaluate('(e)=>{const r=e.getBoundingClientRect();return r.left>=0 && r.right<=innerWidth}'))
  if width==390:page.screenshot(path=str(out/'mobile.png'),full_page=True)
 page.set_viewport_size({'width':1440,'height':1050})
 page.locator('#evaluation').screenshot(path=str(out/'results.png'))
 page.locator('#transfer').screenshot(path=str(out/'transfer.png'))
 check('No failed local project assets',not bad_assets);check('No browser runtime errors',not errors)
 # The alias route uses the same self-contained project component.
 page.goto(args.url.rstrip('/')+'/embodied-rsi/',wait_until='networkidle');check('Project subroute',page.title().startswith('EmbodiedEvo'))
 # A failed data request gives an actionable retry, and retry recovers.
 errorpage=context.new_page();errorpage.route('**/embodied-rsi/data/robotwin.json',lambda route:route.fulfill(status=503,body='unavailable'))
 errorpage.goto(args.url,wait_until='networkidle');check('Data load error shown',errorpage.locator('#episode-error').is_visible())
 errorpage.unroute('**/embodied-rsi/data/robotwin.json');errorpage.locator('#retry-episode').click();errorpage.wait_for_selector('#replay:not([hidden])');check('Data retry recovers',errorpage.locator('#replay').is_visible())
 nojs=b.new_context(java_script_enabled=False,viewport={'width':390,'height':900})
 static=nojs.new_page();static.goto(args.url,wait_until='networkidle')
 check('Core results without JavaScript','30.17%' in static.locator('#input-panel-description').inner_text())
 check('Wiki fallback without JavaScript','35.08%' in static.locator('noscript').all_text_contents()[0])
 b.close()
(out/'browser-checks.json').write_text(json.dumps({'checks':checks,'runtime_errors':errors,'failed_assets':bad_assets},indent=2))
print(json.dumps({'passed':len(checks),'runtime_errors':errors,'failed_assets':bad_assets},indent=2))
